def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    def segments(length, cuts):
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append(list(range(start, cut)))
            start = cut + 1
        if start < length:
            result.append(list(range(start, length)))
        return result

    row_groups = segments(h, sep_rows)
    col_groups = segments(w, sep_cols)

    source = None
    best = -1
    for ri, rows in enumerate(row_groups):
        for ci, cols in enumerate(col_groups):
            score = sum(grid[r][c] != background for r in rows for c in cols)
            if score > best:
                best = score
                source = (ri, ci)

    out = [row[:] for row in grid]
    if source is None or best == 0:
        return out

    src_rows = row_groups[source[0]]
    src_cols = col_groups[source[1]]
    for rows in row_groups:
        for cols in col_groups:
            for i, r in enumerate(rows):
                for j, c in enumerate(cols):
                    if i < len(src_rows) and j < len(src_cols):
                        out[r][c] = grid[src_rows[i]][src_cols[j]]
    return out
